using cstr = const char*;
using cwstr = const wchar_t*;
using cstr16 = const char16_t*;
using cstr32 = const char32_t*;

using str = std::string;
using wstr = std::wstring;
using str16 = std::u16string;
using str32 = std::u32string;

using strview = std::string_view;
using sstream = std::stringstream;
using ostream = std::ostringstream;


template <typename T>
concept Strings =
    std::same_as<T, str>
    || std::same_as<T, cstr>;


template <typename T>
concept WStrings =
    std::same_as<T, wstr>
    || std::same_as<T, cwstr>;
# 7 "./Tools/Types/Types.common.hpp" 2



template <typename X, typename Y>
concept Same = std::same_as<X, Y>;

template <typename T, typename... Ts>
concept OneOf = (Same<T, Ts> || ...);





template <typename T>
concept Nx32 = OneOf<T, i32, f32>;

template <typename T>
concept Nx64 = OneOf<T, i64, f64>;

template <typename T>
concept CNumber = OneOf<T, i32, i64, u32, u64, f32, f64, sidx>;

template <typename T>
concept CTypes = OneOf<T, i32, i64, f32, f64, cstr, str>;

template <typename T>
concept CSize = OneOf<T, idx, sidx>;

template <typename T>
concept Numbers = OneOf<T, i8, i16, i32, i64,
                           u8, u16, u32, u64,
                           f32, f64, fld,
                           sidx, idx
                  >;

template <typename T>
concept Integer = OneOf<T, i8, i16, i32, i64,
                           u8, u16, u32, u64
                           >;

template <typename T>
concept Ref = OneOf<T, T&, const T&>;

template <Numbers T>
void CheckRange(T& min, T& max) {
    if (max < min) std::swap(min, max);
}

template <Numbers T>
std::pair<T, T> CheckRangeR(T min, T max) {
    if (max < min) return std::pair<T, T>(max, min);
}
