namespace RandomHW::Tests {
    const str OK = Tools::Styling::ColorFG("supported", 0xAFCB65);
    const str BAD = Tools::Styling::ColorFG("unsupported", 0xAC2E24);

    bool RDseedSupport() {
        u32 eax, ebx, ecx, edx;
        __asm("  xchg{q|}  {%%|}rbx,%q1\n" "  cpuid\n" "  xchg{q|}  {%%|}rbx,%q1" : "=a"(eax), "=r"(ebx), "=c"(ecx), "=d"(edx) : "0"(7), "2"(0));
        return ebx & 1 << 18;
    }

    pair<bool, bool> TestRandSeed(u16& outA, u16& outB){
        const bool a = _rdrand16_step(&outA);
        const bool b = _rdseed16_step(&outB);
        return {a, b};
    }

    pair<bool, bool> TestRandSeed(u32& outA, u32& outB){
        const bool a = _rdrand32_step(&outA);
        const bool b = _rdseed32_step(&outB);
        return {a, b};
    }

    pair<bool, bool> TestRandSeed(u64& outA, u64& outB){
        const bool a = _rdrand64_step(&outA);
        const bool b = _rdseed64_step(&outB);
        return {a, b};
    }

    void CheckCompatibily(){
        std::cout << std::format("CPU HWRD is {}\n", RDseedSupport() ? OK : BAD);

        u16 out16A{}, out16B{};
        auto Result16 = TestRandSeed(out16A, out16B);
        std::cout << std::format("{}\n",
            std::format("{} {}\n{} {}",
                "16-bit seeder is    ",
                Result16.first,
                "16-bit randomzer is ",
                Result16.second
            )
        );

        u32 out32A{}, out32B{};
        auto Result32 = TestRandSeed(out32A, out32B);
        std::cout << std::format("{}\n",
            std::format("{} {}\n{} {}",
                "32-bit seeder is    ",
                Result32.first,
                "32-bit randomzer is ",
                Result32.second
            )
        );

        u64 out64A{}, out64B{};
        auto Result64 = TestRandSeed(out64A, out64B);
        std::cout << std::format("{}\n\n",
            std::format("{} {}\n{} {}",
                "64-bit seeder is    ",
                Result64.first,
                "64-bit randomzer is ",
                Result64.second
            )
        );
    }
}

