namespace Tools::Win32::File {
    cstr static cstr_safe(strview s, str& temp) {
        if (s.data()[s.size()] == '\0')
            return s.data();

        temp.assign(s);
        return temp.c_str();
    }

    bool WriteFile(strview path, strview text){
        str temp;
        cstr p = cstr_safe(path, temp);

        HANDLE h = CreateFileA(
            p,
            (0x40000000l),
            0,
            nullptr,
            2,
            0x00000080,
            nullptr
        );

        if (h == ((HANDLE) (LONG_PTR)-1)) {return false;}

        DWORD written = 0;
        BOOL ok = ::WriteFile(
            h,
            text.data(),
            (DWORD)text.size(),
            &written,
            nullptr
        );

        CloseHandle(h);
        return ok && written == text.size();
    }

    str ReadFile(strview path) {
        str temp;
        cstr p = cstr_safe(path, temp);

        HANDLE h = CreateFileA(
            p,
            (0x80000000l),
            0x00000001,
            nullptr,
            3,
            0x00000080,
            nullptr
        );

        if (h == ((HANDLE) (LONG_PTR)-1))
            return {};

        LARGE_INTEGER size;
        GetFileSizeEx(h, &size);

        str out;
        out.resize(size.QuadPart);

        DWORD read = 0;
        ::ReadFile(
            h,
            out.data(),
            (DWORD)out.size(),
            &read,
            nullptr
        );

        CloseHandle(h);
        return out;
    }


    bool Exists(strview path) {
        str temp;
        cstr p = cstr_safe(path, temp);

        DWORD attr = GetFileAttributesA(p);
        return attr != ((DWORD)-1);
    }

    bool Remove(strview path) {
        str temp;
        cstr p = cstr_safe(path, temp);

        return DeleteFileA(p);
    }

    bool Move(strview from, strview to) {
        str ftmp, ttmp;
        cstr f = cstr_safe(from, ftmp);
        cstr t = cstr_safe(to, ttmp);

        return MoveFileA(f, t);
    }
}
