namespace Tools::OS::Process {
    template <typename T>
    T ReadProcess(idx PID, uintptr_t Address){
        HANDLE h = OpenProcess(
            (0x0010),
            0,
            (DWORD)PID
        );

        T value{};
        if (!h) return value;

        SIZE_T bytes = 0;
        ReadProcessMemory(
            h,
            (LPCVOID)Address,
            &value,
            sizeof(T),
            &bytes
        );

        CloseHandle(h);
        return value;
    }

    template <typename T>
    bool WriteProcess(idx PID, uintptr_t Address, T data){
        HANDLE h = OpenProcess(
            (0x0020) | (0x0008),
            0,
            (DWORD)PID
        );

        if (!h) return false;

        SIZE_T bytes = 0;
        BOOL ok = WriteProcessMemory(
            h,
            (LPVOID)Address,
            &data,
            sizeof(T),
            &bytes
        );

        CloseHandle(h);
        return ok && bytes == sizeof(T);
    }


    bool IsAdmin() {
        BOOL isAdmin = 0;
        HANDLE token = nullptr;

        if (!OpenProcessToken(GetCurrentProcess(), (0x0008), &token))
            return false;

        SID_IDENTIFIER_AUTHORITY NtAuth = {0,0,0,0,0,5};
        PSID adminGroup = nullptr;

        AllocateAndInitializeSid(
            &NtAuth,
            2,
            (0x00000020l),
            (0x00000220l),
            0,0,0,0,0,0,
            &adminGroup
        );

        CheckTokenMembership(token, adminGroup, &isAdmin);

        FreeSid(adminGroup);
        CloseHandle(token);

        return isAdmin;
    }


    bool IsAdmin(idx pid) {
        HANDLE proc = OpenProcess((0x1000), 0, (DWORD)pid);
        if (!proc) return false;

        HANDLE token = nullptr;
        if (!OpenProcessToken(proc, (0x0008), &token)) {
            CloseHandle(proc);
            return false;
        }

        BOOL isAdmin = 0;
        SID_IDENTIFIER_AUTHORITY NtAuth = {0,0,0,0,0,5};
        PSID adminGroup = nullptr;

        AllocateAndInitializeSid(
            &NtAuth,
            2,
            (0x00000020l),
            (0x00000220l),
            0,0,0,0,0,0,
            &adminGroup
        );

        CheckTokenMembership(token, adminGroup, &isAdmin);

        FreeSid(adminGroup);
        CloseHandle(token);
        CloseHandle(proc);

        return isAdmin;
    }
}
