template <typename T>
__inline__ T& Tools::ivec<T>::refbegin() {
    if (ivec_size == 0)
        throw std::out_of_range("ivec is empty");
    return ivec_data[0];
}


template <typename T>
__inline__ T& Tools::ivec<T>::refend() {
    if (ivec_size == 0)
        throw std::out_of_range("ivec is empty");
    return ivec_data[ivec_size - 1];
}
